# target_module.py

def verify_schema(schema_def: dict) -> list:
    """
    Verifies relational database schema invariants and detects:
    1. Missing primary keys.
    2. Unindexed foreign key columns.
    3. Non-null constraint drift (e.g., mismatch or unexpected nullable state).

    Parameters:
    - schema_def (dict): A dictionary representing the database schema.
      Expected structure:
      {
          "tables": {
              "table_name": {
                  "columns": {
                      "col_name": {
                          "nullable": bool,
                          "type": str,
                          "primary_key": bool,
                          "foreign_key": bool, # or dict referencing table/col
                          "indexed": bool
                      }
                  },
                  "primary_key": ["col1", ...], # optional table-level definition
                  "foreign_keys": [
                      {
                          "columns": ["col1"],
                          "referenced_table": "other_table",
                          "referenced_columns": ["col1"],
                          "indexed": bool # optional explicit index check for FK
                      }
                  ],
                  "indexes": [["col1", ...], ...]
              }
          },
          "drift_baseline": {
              "tables": {
                  "table_name": {
                      "columns": {
                          "col_name": {
                              "nullable": bool
                          }
                      }
                  }
              }
          }
      }

    Returns:
    - list of str: Descriptions of detected invariant violations or drift.
    """
    violations = []

    if not isinstance(schema_def, dict):
        return ["Invalid schema definition format: expected a dictionary."]

    tables = schema_def.get("tables", {})
    if not isinstance(tables, dict):
        return ["Invalid schema definition format: 'tables' must be a dictionary."]

    baseline = schema_def.get("drift_baseline", {}).get("tables", {})
    if not isinstance(baseline, dict):
        baseline = {}

    for table_name, table_info in tables.items():
        if not isinstance(table_info, dict):
            violations.append(f"Table '{table_name}' definition must be a dictionary.")
            continue

        columns = table_info.get("columns", {})
        if not isinstance(columns, dict):
            columns = {}

        # 1. Check for missing primary keys
        table_pk = table_info.get("primary_key", [])
        column_pks = [col_name for col_name, col_def in columns.items() if isinstance(col_def, dict) and col_def.get("primary_key", False)]

        if not table_pk and not column_pks:
            violations.append(f"Table '{table_name}' is missing a primary key.")

        # Collect all indexed columns for foreign key index checks
        indexes = table_info.get("indexes", [])
        indexed_cols = set()
        if isinstance(indexes, list):
            for idx in indexes:
                if isinstance(idx, list):
                    indexed_cols.update(idx)

        for col_name, col_def in columns.items():
            if isinstance(col_def, dict) and col_def.get("indexed", False):
                indexed_cols.add(col_name)

        # 2. Check for unindexed foreign key columns
        foreign_keys = table_info.get("foreign_keys", [])
        if not isinstance(foreign_keys, list):
            foreign_keys = []
        else:
            foreign_keys = list(foreign_keys)

        # Also check column-level foreign key definitions
        for col_name, col_def in columns.items():
            if not isinstance(col_def, dict):
                continue
            fk_def = col_def.get("foreign_key")
            if fk_def is not None:
                if isinstance(fk_def, dict):
                    referenced_table = fk_def.get("referenced_table")
                else:
                    referenced_table = str(fk_def)
                foreign_keys.append({
                    "columns": [col_name],
                    "referenced_table": referenced_table,
                    "indexed": col_def.get("indexed", False) or (col_name in indexed_cols)
                })

        for fk in foreign_keys:
            if not isinstance(fk, dict):
                continue
            fk_cols = fk.get("columns", [])
            if not isinstance(fk_cols, list) or not fk_cols:
                continue

            # Check if explicitly marked as indexed in FK definition or if columns are present in indexes.
            # For multi-column foreign keys, standard B-tree indexing on leading columns or full composite is checked.
            is_indexed = fk.get("indexed", False) or all(col in indexed_cols for col in fk_cols)

            if not is_indexed:
                cols_str = ", ".join(str(c) for c in fk_cols)
                violations.append(f"Table '{table_name}' has an unindexed foreign key on column(s): {cols_str}.")

        # 3. Check for non-null constraint drift against baseline
        baseline_table = baseline.get(table_name, {})
        if not isinstance(baseline_table, dict):
            continue
        baseline_cols = baseline_table.get("columns", {})
        if not isinstance(baseline_cols, dict):
            continue

        for col_name, col_def in columns.items():
            if not isinstance(col_def, dict):
                continue
            if col_name in baseline_cols:
                current_nullable = col_def.get("nullable")
                baseline_col_def = baseline_cols[col_name]
                if not isinstance(baseline_col_def, dict):
                    continue
                baseline_nullable = baseline_col_def.get("nullable")

                if current_nullable is not None and baseline_nullable is not None:
                    if current_nullable != baseline_nullable:
                        violations.append(
                            f"Non-null constraint drift detected on '{table_name}.{col_name}': "
                            f"baseline nullable={baseline_nullable}, current nullable={current_nullable}."
                        )

    return violations
